using KitWright.Editor.Tools.Scripting;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
using System.Text;

public class CommandScript : IKitWrightCommand
{
    public void Execute(ExecutionContext ctx)
    {
        var sb = new StringBuilder();
        var scene = EditorSceneManager.GetActiveScene();
        if (!scene.path.Contains("LoginMenu"))
            scene = EditorSceneManager.OpenScene("Assets/Project/LoginMenu.unity");

        Transform FindDeep(string name)
        {
            foreach (var t in Resources.FindObjectsOfTypeAll<Transform>())
            {
                if (EditorUtility.IsPersistent(t.gameObject)) continue;
                if (t.name == name) return t;
            }
            return null;
        }

        var logo = FindDeep("Logo_Railbound_Yellow");
        var dock = FindDeep("LoginDock");
        var loginPanel = FindDeep("LoginPanel");
        sb.AppendLine("logo=" + (logo != null) + " dock=" + (dock != null) + " panel=" + (loginPanel != null));

        var parent = dock != null ? dock : loginPanel;
        if (logo != null && parent != null)
        {
            ctx.RegisterObjectModification(logo.gameObject);
            logo.SetParent(parent, false);
            logo.SetAsFirstSibling();
            var rt = logo.GetComponent<RectTransform>();
            rt.anchorMin = new Vector2(0.5f, 1f);
            rt.anchorMax = new Vector2(0.5f, 1f);
            rt.pivot = new Vector2(0.5f, 0f);
            rt.sizeDelta = new Vector2(260f, 70f);
            rt.anchoredPosition = new Vector2(0f, 12f);
            sb.AppendLine("reparented logo to " + parent.name);
        }

        // Wire missing title/subtitle refs on LoginUI if present in hierarchy
        var loginUi = Object.FindObjectOfType<LoginUI>(true);
        if (loginUi != null)
        {
            var so = new SerializedObject(loginUi);
            void TryWire(string prop, string objName)
            {
                var p = so.FindProperty(prop);
                if (p == null || p.objectReferenceValue != null) return;
                var t = FindDeep(objName);
                if (t == null) return;
                var tmp = t.GetComponent<TMP_Text>();
                if (tmp == null) return;
                p.objectReferenceValue = tmp;
                sb.AppendLine("wired " + prop + " -> " + objName);
            }
            TryWire("gameTitle", "GameTitle");
            TryWire("gameTitle", "Title");
            TryWire("subtitle", "Subtitle");
            TryWire("subtitle", "PopupSubtitle");
            so.ApplyModifiedPropertiesWithoutUndo();
            ctx.RegisterObjectModification(loginUi);

            if (loginUi.gameTitle != null)
            {
                loginUi.gameTitle.text = "RAILBOUND";
                loginUi.gameTitle.color = new Color(1f, 0.816f, 0f, 1f);
            }
            if (loginUi.subtitle != null)
            {
                loginUi.subtitle.text = "ENTER THE IRONLINE";
                loginUi.subtitle.color = new Color(0.576f, 0.635f, 0.686f, 1f);
            }
        }

        // List top canvas children for sanity
        var canvas = FindDeep("Canvas");
        if (canvas != null)
        {
            for (int i = 0; i < canvas.childCount; i++)
                sb.AppendLine("canvas/" + canvas.GetChild(i).name + " active=" + canvas.GetChild(i).gameObject.activeSelf);
        }

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        ctx.ReturnValue = sb.ToString();
    }
}
